  var BPM = 130;
  var BEAT = 60 / BPM;
  var beatTime = (n) => n * BEAT;
  var T_START = 14;
  var T_END = 29.74;
  var WAVE_BEATS = [32, 34, 36, 38, 40, 42];
  var WORLD5_BEAT = 40;
  var MONOLITH_BEAT = 53;
  var SKYLINE_BEAT = 54;
  var RING_BEATS = [40, 42, 44, 46, 48];
  var ORB_A_T = T_START + 0.4;
  var ORB_B_T = T_START + 2.2;
