      const envA = fade(tLocal, 0, 0.55, 3.25, 3.7);
      const envB = fade(tLocal, 3.3, 3.85, 6.95, 7.55);
      const envC = fade(tLocal, 7.1, 7.6, 10.6, 11.25);
      const envD = fade(tLocal, 10.8, 11.35, 15.6, 16.4);
      const envAmb = fade(tLocal, 0, 1, 14.8, 16);
