      this.env.bg = this._bg.getHex();
      this.env.fogDensity = this.palette.fogDensity * (1 + 0.2 * flare);
      this.env.bloom = 0.9 + 0.15 * flare + 0.08 * flareSpike;
      this.fx.bloom = 0.1 * flareSpike + 0.08 * flare;
      this.fx.flash = 0.06 * flareSpike;
      this.amb.update(tAbs);
      this.amb.points.material.opacity = 0.2 * envAmb * w * (0.7 + 0.3 * mid);
