        QT.set(this._axis[i * 3] * sha, this._axis[i * 3 + 1] * sha, this._axis[i * 3 + 2] * sha, Math.cos(ha));
        QR.set(0, sy2, 0, cy2);
        QB.set(this._bquat[i * 4], this._bquat[i * 4 + 1], this._bquat[i * 4 + 2], this._bquat[i * 4 + 3]);
        QR.multiply(QT).multiply(QB);
