        lp[k * 6 + 2] = this._rp[a * 3 + 2];
        lp[k * 6 + 3] = this._rp[b * 3];
        lp[k * 6 + 4] = this._rp[b * 3 + 1];
        lp[k * 6 + 5] = this._rp[b * 3 + 2];
