        spp[k * 3 + 1] = this._spEmit[k * 3 + 1] + this._spVel[k * 3 + 1] * tau - 0.3 * tau * tau;
        spp[k * 3 + 2] = this._spEmit[k * 3 + 2] + this._spVel[k * 3 + 2] * tau + 0.05 * tau * Math.cos(tAbs * 2.9 + k);
