        B[0] = fr[0] * (1 + dist / dl) + 0.3 * Math.sin(tLocal * 0.7);
        B[1] = fr[1] + 0.85 + 0.2 * Math.sin(tLocal * 0.5);
        B[2] = fr[2] * (1 + dist / dl) + 0.3 * Math.cos(tLocal * 0.6);
        fovB = 45 - 5 * push;
        wB = u.smoothstep(tLocal, 3.55, 3.9);
