        const a = i / n * TAU3 + (inner ? 0.15 : 0) + (rand() - 0.5) * 0.08;
        this.colX[c] = Math.cos(a) * r;
        this.colZ[c] = Math.sin(a) * r;
        this.colNseg[c] = inner ? 11 + Math.floor(rand() * 6) : 8 + Math.floor(rand() * 6);
        this.colPhase[c] = rand() * TAU3;
