          if (colFlash > 0.01) c.lerp(this._cWhite, Math.min(0.65, colFlash));
          c.multiplyScalar(bright * w);
          o.position.set(x, y, z);
          o.rotation.set(rx, 0, rz);
          o.scale.setScalar(sc);
          o.updateMatrix();
          inst.setMatrixAt(idx, o.matrix);
          inst.setColorAt(idx, c);
